 "cap": [
  {
   "cap_id": "P0080",
   "a": {
    "unit_id": "BLLD_45-2019.D34.K10",
    "tieu_de_dieu": "Các trường hợp chấm dứt hợp đồng lao động",
    "khoan_cha": "",
    "chu_don_vi": "Người sử dụng lao động đơn phương chấm dứt hợp đồng lao động theo quy định tại Điều 36 của Bộ luật này."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D177.K3",
    "tieu_de_dieu": "Nghĩa vụ của người sử dụng lao động đối với tổ chức đại diện người lao động tại cơ sở",
    "khoan_cha": "",
    "chu_don_vi": "Phải thỏa thuận bằng văn bản với ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở khi đơn phương chấm dứt hợp đồng lao động, chuyển làm công việc khác, kỷ luật sa thải đối với người lao động là thành viên ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở. Trường hợp không thỏa thuận được, hai bên phải báo cáo với cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh. Sau 30 ngày kể từ ngày báo cho cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh biết, người sử dụng lao động mới có quyền quyết định. Trường hợp không nhất trí với quyết định của người sử dụng lao động thì người lao động, ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở có quyền yêu cầu giải quyết tranh chấp lao động theo trình tự, thủ tục do pháp luật quy định."
   },
   "vi_tu_chung": [
    "employer_unilateral_termination"
   ]
  },
  {
   "cap_id": "P0081",
   "a": {
    "unit_id": "BLLD_45-2019.D34.K11",
    "tieu_de_dieu": "Các trường hợp chấm dứt hợp đồng lao động",
    "khoan_cha": "",
    "chu_don_vi": "Người sử dụng lao động cho người lao động thôi việc theo quy định tại Điều 42 và Điều 43 của Bộ luật này."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D42.K6",
    "tieu_de_dieu": "Nghĩa vụ của người sử dụng lao động trong trường hợp thay đổi cơ cấu, công nghệ hoặc vì lý do kinh tế",
    "khoan_cha": "",
    "chu_don_vi": "Việc cho thôi việc đối với người lao động theo quy định tại Điều này chỉ được tiến hành sau khi đã trao đổi ý kiến với tổ chức đại diện người lao động tại cơ sở đối với nơi có tổ chức đại diện người lao động tại cơ sở mà người lao động là thành viên và thông báo trước 30 ngày cho Ủy ban nhân dân cấp tỉnh và cho người lao động."
   },
   "vi_tu_chung": [
    "lay_off"
   ]
  },
